WITH parsed AS (SELECT id, log_ts, level, context, COALESCE(context['version'], 'unknown') AS version_or_default, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, context['trace'] AS trace FROM app_logs) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, COUNT(*) AS event_count, COUNT(DISTINCT level) AS distinct_levels, GROUPING_ID() AS grouping_id FROM parsed GROUP BY CUBE (DATE_TRUNC('HOUR', log_ts)) ORDER BY distinct_levels;
